from pathlib import Path
import json,re,hashlib
from collections import defaultdict
R=Path.cwd();U=R/'unity/VideoEditing';H=R/'projects/animation-exaggeration/production/grid-v1'
read=lambda p:json.loads(p.read_text('utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
p=read(H/'source-closure-plan.json');mapping=defaultdict(list)
# Installed package metadata is read-only evidence, never an owned commit candidate.
for root in [U/'Assets',U/'Packages',U/'Library/PackageCache']:
 if not root.exists():continue
 for meta in root.rglob('*.meta'):
  try:text=meta.read_text('utf-8-sig')
  except (UnicodeError,OSError):continue
  m=re.search(r'^guid: ([a-f0-9]{32})$',text,re.M)
  if m:mapping[m[1]].append(meta.with_suffix(''))
visited=set();rows=[];edges=[];unresolved=[];duplicates=[];builtins=[];missing=[]
known_builtins={'00000000000000000000000000000000','0000000000000000e000000000000000','0000000000000000f000000000000000'}
def visit(target,reason):
 target=target.resolve()
 if target in visited:return
 visited.add(target)
 if not target.is_relative_to(U.resolve()) or not target.is_file():missing.append(str(target));return
 meta=Path(str(target)+'.meta');relative=target.relative_to(R).as_posix()
 if not meta.exists():missing.append(str(meta));return
 family='licensed-local-only' if '/ThirdParty/YamyamAssetLibrary/' in relative else ('installed-package-only' if '/Library/PackageCache/' in relative or '/Packages/' in relative else 'asset-candidate')
 text_meta=meta.read_text('utf-8-sig');m=re.search(r'^guid: ([a-f0-9]{32})$',text_meta,re.M)
 if not m:missing.append(str(meta)+' has no GUID');return
 rows.append({'path':relative,'sha256':sha(target),'metaPath':meta.relative_to(R).as_posix(),'metaSha256':sha(meta),'guid':m[1],'family':family,'reason':reason})
 texts=[text_meta]
 if target.suffix.lower() in {'.unity','.prefab','.mat','.asset','.controller','.overridecontroller','.anim','.json','.shadergraph','.shadersubgraph'}:
  try:texts.append(target.read_text('utf-8-sig'))
  except UnicodeError:pass
 for text in texts:
  for value in set(re.findall(r'guid: ([a-f0-9]{32})',text)):
   if value==m[1]:continue
   if value in known_builtins:builtins.append({'from':relative,'guid':value});continue
   candidates=list(dict.fromkeys(mapping.get(value,[])))
   if len(candidates)!=1:
    item={'from':relative,'guid':value,'candidates':[x.relative_to(R).as_posix() for x in candidates]}
    (unresolved if not candidates else duplicates).append(item);continue
   dep=candidates[0];edges.append({'from':relative,'guid':value,'to':dep.relative_to(R).as_posix()});visit(dep,'GUID dependency')
 if target.suffix.lower()=='.png' and '/animation-exaggeration/grid-v1/Generated/ReferenceImages/' in relative:
  visit(Path(str(target)+'.source.json'),'own-label provenance')
for entry in p['expectedFinalScenes']:
 receipt=read(R/entry['expectedRenderReceipt']);assert receipt['status']=='complete'
 visit(R/entry['expectedScene'],'final saved scene');visit(R/entry['expectedCaptureStamp'],'scene source stamp')
 for name in receipt['assets']+receipt['animations']:visit(U/name,'runtime string-loaded dependency')
for entry in p['currentSourceIdentities']:visit(R/entry['asset']['path'],'explicit reconstruction code/profile dependency')
# Folder identity matters even where no explicit YAML GUID edge names the parent.
folder_meta=[]
for row in rows:
 for parent in (R/row['path']).parents:
  if parent==U/'Assets' or not parent.is_relative_to(U/'Assets'):break
  meta=Path(str(parent)+'.meta')
  if meta.is_file() and meta.as_posix() not in {x['absolute'] for x in folder_meta}:folder_meta.append({'absolute':meta.as_posix(),'path':meta.relative_to(R).as_posix(),'sha256':sha(meta)})
print(json.dumps({'status':'guid-closure-needs-review' if unresolved or duplicates or missing else 'guid-closure-resolved-file-only','files':rows,'edges':edges,'packageOrBuiltinReferences':builtins,'unresolvedGuids':unresolved,'duplicateGuidReferences':duplicates,'missingFilesOrMetas':missing,'folderMetas':folder_meta,'important':'Do not commit licensed-local-only/package/cache rows. Final exact owned list and essential-image registration remain separate; no metadata or Git mutation occurred.'},ensure_ascii=False,indent=2))
